"""Create explicit, reviewable presentation-only rewrites of technical footnotes."""
from pathlib import Path
import importlib.util,json,re
ROOT=Path(__file__).resolve().parents[2]
spec=importlib.util.spec_from_file_location('reader',ROOT/'tools/build_rr_reader.py');b=importlib.util.module_from_spec(spec);spec.loader.exec_module(b)
target=ROOT/'tools/rr_reader_notes.json'
assert not target.exists(),'The explicit projection already exists; edit it rather than regenerating from projected output.'
text=b.CANONICAL.read_text('utf-8')
notes=[re.sub(r'^> \\\*\d*\s*','',n) for n in b.notes(text)]
items=[]
def add(needle,reading):
    matches=[n for n in notes if needle in n];assert len(matches)==1,(needle,len(matches))
    source=matches[0];at=text.index(source)
    page=int(re.findall(r'id="pdf-page-(\d+)"',text[:at])[-1])
    items.append({'pdf_page':page,'original':source,'reading':reading})

